{"code":"import pandas as pd
import numpy as np

# Let's write our scorer and compare with pipeline_output.csv
raw = pd.read_csv('raw_responses.csv')
pipeline = pd.read_csv('pipeline_output.csv')

def score_phq9(row):
    items = [f'phq9_{i}' for i in range(1, 10)]
    vals = []
    for it in items:
        v = row[it]
        if pd.isna(v) or v == -9 or v < 0 or v > 3:
            vals.append(None)
        else:
            vals.append(int(v))

    valid_vals = [v for v in vals if v is not None]
    n_missing = len(vals) - len(valid_vals)

    if n_missing >= 2:
        return pd.Series({'phq9_total': np.nan, 'phq9_band': np.nan, 'phq9_prorated': np.nan, 'phq9_self_harm_flag': np.nan})

    if n_missing == 0:
        total = sum(valid_vals)
        prorated = False
    elif n_missing == 1:
        # sum * 9 / 8, round to whole, halves round up
        # how to implement round up for .5? Decimal or np.floor(x + 0.5)
        raw_sum = sum(valid_vals)
        scaled = raw_sum * 9 / 8
        # round half up:
        from decimal import Decimal, ROUND_HALF_UP
        total = int(Decimal(str(scaled)).quantize(Decimal('1'), rounding=ROUND_HALF_UP))
        prorated = True

    # band
    if total <= 4:
        band = 'none-minimal'
    elif total <= 9:
        band = 'mild'
    elif total <= 14:
        band = 'moderate'
    elif total <= 19:
        band = 'moderately severe'
    else:
        band = 'severe'

    # self harm flag (q9)
    q9 = row['phq9_9']
    if pd.isna(q9) or q9 == -9 or q9 < 0 or q9 > 3:
        sh_flag = np.nan
    else:
        sh_flag = (int(q9) > 0)

    return pd.Series({'phq9_total': float(total), 'phq9_band': band, 'phq9_prorated': prorated, 'phq9_self_harm_flag': sh_flag})

def score_gad7(row):
    items = [f'gad7_{i}' for i in range(1, 8)]
    vals = []
    for it in items:
        v = row[it]
        if pd.isna(v) or v == -9 or v < 0 or v > 3:
            vals.append(None)
        else:
            vals.append(int(v))

    valid_vals = [v for v in vals if v is not None]
    n_missing = len(vals) - len(valid_vals)

    if n_missing >= 2:
        return pd.Series({'gad7_total': np.nan, 'gad7_band': np.nan, 'gad7_prorated': np.nan})

    if n_missing == 0:
        total = sum(valid_vals)
        prorated = False
    elif n_missing == 1:
        raw_sum = sum(valid_vals)
        scaled = raw_sum * 7 / 6
        from decimal import Decimal, ROUND_HALF_UP
        total = int(Decimal(str(scaled)).quantize(Decimal('1'), rounding=ROUND_HALF_UP))
        prorated = True

    if total <= 4:
        band = 'minimal'
    elif total <= 9:
        band = 'mild'
    elif total <= 14:
        band = 'moderate'
    else:
        band = 'severe'

    return pd.Series({'gad7_total': float(total), 'gad7_band': band, 'gad7_prorated': prorated})

def score_rses(row):
    items = [f'rses_{i}' for i in range(1, 11)]
    rev_items = {3, 5, 8, 9, 10}
    vals = []
    for i, it in enumerate(items, 1):
        v = row[it]
        if pd.isna(v) or v == -9 or v < 0 or v > 3:
            vals.append(None)
        else:
            ans = int(v)
            if i in rev_items:
                vals.append(3 - ans)
            else:
                vals.append(ans)

    valid_vals = [v for v in vals if v is not None]
    n_missing = len(vals) - len(valid_vals)

    if n_missing >= 2:
        return pd.Series({'rses_total': np.nan, 'rses_prorated': np.nan})

    if n_missing == 0:
        total = sum(valid_vals)
        prorated = False
    elif n_missing == 1:
        raw_sum = sum(valid_vals)
        scaled = raw_sum * 10 / 9
        from decimal import Decimal, ROUND_HALF_UP
        total = int(Decimal(str(scaled)).quantize(Decimal('1'), rounding=ROUND_HALF_UP))
        prorated = True

    return pd.Series({'rses_total': float(total), 'rses_prorated': prorated})

my_out = []
for idx, row in raw.iterrows():
    res = pd.Series({'respondent_id': row['respondent_id']})
    res = pd.concat([res, score_phq9(row), score_gad7(row), score_rses(row)])
    my_out.append(res)
my_df = pd.DataFrame(my_out)

# Compare columns
for col in pipeline.columns:
    if col == 'respondent_id':
        continue
    mismatches = (pipeline[col].values != my_df[col].values) & ~(pd.isna(pipeline[col]) & pd.isna(my_df[col]))
    print(f"Col {col}: {mismatches.sum()} mismatches")
    if mismatches.sum() > 0:
        bad_idx = np.where(mismatches)[0]
        print("  Example mismatch rows:", bad_idx[:5])
        print("  Pipeline:", pipeline.loc[bad_idx[:3], col].values)
        print("  My scorer:", my_df.loc[bad_idx[:3], col].values)
"}

