import numpy as np

raw = pd.read_csv('raw_responses.csv')
pipeline = pd.read_csv('pipeline_output.csv')

# Let's check what happens if we add 1 to each valid PHQ-9 item
def test_phq9(row):
    items = [f'phq9_{i}' for i in range(1, 10)]
    vals = []
    for it in items:
        v = row[it]
        if pd.isna(v) or v == -9 or v < 0:
            vals.append(None)
        else:
            vals.append(int(v) + 1) # off_by_one: 1-4 instead of 0-3
    valid = [v for v in vals if v is not None]
    if len(valid) < 8:
        return np.nan
    if len(valid) == 8:
        from decimal import Decimal, ROUND_HALF_UP
        return int(Decimal(str(sum(valid) * 9 / 8)).quantize(Decimal('1'), rounding=ROUND_HALF_UP))
    return sum(valid)

my_phq9 = raw.apply(test_phq9, axis=1)
mismatches = (pipeline['phq9_total'].values != my_phq9.values) & ~(pd.isna(pipeline['phq9_total']) & pd.isna(my_phq9))
print("PHQ-9 total mismatches with +1 item shift:", mismatches.sum())
"}

